// Normalize input and determine event type
const input = $input.item.json;

let eventType, eventData;

// From AI Gateway (emergency classification)
if (input.category === 'EMERGENCY') {
  eventType = 'emergency';
  eventData = {
    source: 'guest_report',
    message: input.message_text,
    sender_id: input.sender_id,
    channel: input.channel,
    property_id: input.property_id,
    urgency: 'high'
  };
}
// Screening request
else if (input.guest_email || input.booking_id) {
  eventType = 'screening';
  eventData = {
    booking_id: input.booking_id,
    guest_name: input.guest_name,
    guest_email: input.guest_email,
    guest_phone: input.guest_phone,
    property_id: input.property_id,
    check_in_date: input.check_in_date
  };
}
// Watchdog check
else if (!input.category && !input.guest_email) {
  eventType = 'watchdog';
  eventData = { check_time: new Date().toISOString() };
}
// Generic safety event
else {
  eventType = input.event_type || 'unknown';
  eventData = input;
}

return { event_type: eventType, data: eventData };

