// Analyze watchdog results and generate alerts
const checks = $input.all().map(i => i.json);
const alerts = [];

for (const check of checks) {
  if (check.count > 0) {
    alerts.push({
      type: check.check_type,
      count: check.count,
      severity: check.check_type.includes('emergency') ? 'high' : 'medium',
      message: `${check.count} ${check.check_type.replace(/_/g, ' ')} detected`
    });
  }
}

return {
  alerts: alerts,
  total_issues: alerts.reduce((sum, a) => sum + a.count, 0),
  check_time: new Date().toISOString(),
  status: alerts.length > 0 ? 'issues_found' : 'healthy'
};

// Return result to calling workflow
return {
  success: true,
  event_type: $('Normalize Event').item.json.event_type,
  processed: true,
  result: $input.item.json
};
